protected void btnUpdateMarks_Click(object sender, EventArgs e)
{
    string studentCode, yearId, semester, planId;
    if (!TryDecodeStudentInfo(out studentCode, out yearId, out semester, out planId))
        return;

    try
    {
        POL_DoneDetail obj = new POL_DoneDetail();
        decimal totalStudentMarks = 0;
        decimal totalTeacherMarks = 0;

        // Dictionary lưu tổng điểm theo từng QuestionCode (N1, N2, ...)
        Dictionary<string, decimal> dictMarkByQuestionCode = new Dictionary<string, decimal>();

        // Cập nhật từng dòng điểm giáo viên + tính tổng từ GridView đang hiển thị
        foreach (GridViewRow row in gvData.Rows)
        {
            if (row.RowType != DataControlRowType.DataRow) continue;

            decimal studentMark = GetGridStudentMark(row);
            decimal teacherMark = GetGridTeacherMark(row, studentMark);

            totalStudentMarks += studentMark;
            totalTeacherMarks += teacherMark;

            // Thu thập điểm theo QuestionCode (N1-N6) để lưu vào SIM_SemesterEthicMark
            HiddenField hdnQuestionCode = row.FindControl("hdnQuestionCode") as HiddenField;
            if (hdnQuestionCode != null && !string.IsNullOrWhiteSpace(hdnQuestionCode.Value))
            {
                string questionCode = hdnQuestionCode.Value.Trim();
                if (dictMarkByQuestionCode.ContainsKey(questionCode))
                    dictMarkByQuestionCode[questionCode] += teacherMark;
                else
                    dictMarkByQuestionCode[questionCode] = teacherMark;
            }

            int doneDetailID = Convert.ToInt32(gvData.DataKeys[row.RowIndex].Value);
            if (doneDetailID <= 0) continue;

            obj.GetDataTable("POL_DoneDetail_UpdateReviewMark",
                "@DoneDetailID", doneDetailID,
                "@ReviewMark", teacherMark);
        }

        // Luôn cập nhật tổng điểm sang SIM_SummaryEthicMark
        UpdateTotalMarks(obj, studentCode, yearId, semester, planId, totalStudentMarks, totalTeacherMarks);

        // Lưu điểm theo từng QuestionCode vào SIM_SemesterEthicMark
        UpdateSemesterEthicMark(obj, studentCode, yearId, semester, dictMarkByQuestionCode);

        MsgBox.ShowSuccess("Cập nhật điểm thành công!");
        LoadData();
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Có lỗi xảy ra trong quá trình cập nhật: " + ex.Message);
    }
}

