private void UpdateTotalMarks(POL_DoneDetail obj, string studentCode, string yearId, string semester, string planId, decimal totalStudentMarks, decimal totalTeacherMarks)
{
    obj.GetDataTable("POL_DoneDetail_UpdateReviewMark_Learning",
        "@StudentCode", studentCode,
        "@YearID", yearId,
        "@Semester", semester,
        "@PlanID", planId,
        "@totalStudent", totalStudentMarks,
        "@totalTeacher", totalTeacherMarks,
        "@UpdatedUser", User != null ? User.UserName : string.Empty);
}

private void UpdateSemesterEthicMark(POL_DoneDetail obj, string studentCode, string yearId, string semester, Dictionary<string, decimal> dictMarkByQuestionCode)
{
    // Lấy điểm cho từng QuestionCode N1-N6, nếu không có thì mặc định NULL
    decimal? mark1 = dictMarkByQuestionCode.ContainsKey("N1") ? (decimal?)dictMarkByQuestionCode["N1"] : null;
    decimal? mark2 = dictMarkByQuestionCode.ContainsKey("N2") ? (decimal?)dictMarkByQuestionCode["N2"] : null;
    decimal? mark3 = dictMarkByQuestionCode.ContainsKey("N3") ? (decimal?)dictMarkByQuestionCode["N3"] : null;
    decimal? mark4 = dictMarkByQuestionCode.ContainsKey("N4") ? (decimal?)dictMarkByQuestionCode["N4"] : null;
    decimal? mark5 = dictMarkByQuestionCode.ContainsKey("N5") ? (decimal?)dictMarkByQuestionCode["N5"] : null;
    decimal? mark6 = dictMarkByQuestionCode.ContainsKey("N6") ? (decimal?)dictMarkByQuestionCode["N6"] : null;

    if (mark1 == null && mark2 == null && mark3 == null
        && mark4 == null && mark5 == null && mark6 == null)
        return;

    int semesterValue;
    int.TryParse(semester, out semesterValue);
    if (semesterValue <= 0)
        return;

    obj.GetDataTable("SIM_SemesterEthicMark_InsertOrUpdate",
        "@StudentCode", studentCode,
        "@YearID", yearId,
        "@Semester", semesterValue,
        "@Mark1", (object)mark1 ?? DBNull.Value,
        "@Mark2", (object)mark2 ?? DBNull.Value,
        "@Mark3", (object)mark3 ?? DBNull.Value,
        "@Mark4", (object)mark4 ?? DBNull.Value,
        "@Mark5", (object)mark5 ?? DBNull.Value,
        "@Mark6", (object)mark6 ?? DBNull.Value,
        "@UpdatedUser", User != null ? User.UserName : string.Empty);
}
#endregion

